-- Postgres dialect of schema/0955_sod_policy_refs.sql (issue #652, AC-6; kept in parity with the SQLite file by
-- TestSchemaParity_SQLiteAndPostgres). Cross-tenant guard triggers become composite foreign keys
-- (tenant_id, x_id) -> (tenant_id, id); see 0001_tenancy.sql. rls.sql is regenerated by `tessera admin gen-rls`.

-- +goose Up

CREATE TABLE sod_policy_refs (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  ruleset_id TEXT NOT NULL,
  ruleset_version BIGINT NOT NULL,
  policy_ref TEXT NOT NULL,
  actor TEXT NOT NULL,
  applied_at TEXT NOT NULL,
  FOREIGN KEY (tenant_id, ruleset_id) REFERENCES sod_rulesets (tenant_id, id)
);
CREATE INDEX ix_sod_policy_refs_tenant_ruleset ON sod_policy_refs (tenant_id, ruleset_id);

CREATE TRIGGER sod_policy_refs_no_update BEFORE UPDATE ON sod_policy_refs
	FOR EACH ROW EXECUTE FUNCTION tessera_abort('sod_policy_refs is append-only');

CREATE TRIGGER sod_policy_refs_no_delete BEFORE DELETE ON sod_policy_refs
	FOR EACH ROW EXECUTE FUNCTION tessera_abort('sod_policy_refs is append-only');
